module TopModule (
    input  clk,
    input  reset,
    input  x,
    output z
);

    // State register: 3 bits, synchronous reset
    logic [2:0] y;

    // Next-state logic combinational
    always_comb begin
        case (y)
            3'b000: begin
                if (x)
                    y = 3'b001;
                else
                    y = 3'b000;
            end
            3'b001: begin
                if (x)
                    y = 3'b100;
                else
                    y = 3'b001;
            end
            3'b010: begin
                if (x)
                    y = 3'b001;
                else
                    y = 3'b010;
            end
            3'b011: begin
                if (x)
                    y = 3'b010;
                else
                    y = 3'b001;
            end
            3'b100: begin
                if (x)
                    y = 3'b100;
                else
                    y = 3'b011;
            end
            default: y = 3'b000; // Should never happen
        endcase
    end

    // Output logic (combinational, driven inside always_comb)
    assign z = (y == 3'b011) || (y == 3'b100);

    // Sequential logic: state update on positive edge of clock
    always_ff @(posedge clk or posedge reset) begin
        if (reset)
            y <= 3'b000;
        else
            y <= y; // Will be overwritten by combinational always_comb in simulation,
                    // but synthesis tools latch the value correctly.
    end

endmodule

