module TopModule (
    input  d,
    input  done_counting,
    input  ack,
    input  [9:0] state,
    output B3_next,
    output S_next,
    output S1_next,
    output Count_next,
    output Wait_next,
    output done,
    output counting,
    output shift_ena
);

    // One-hot encoded state bits (active high)
    wire S_bit       = state[0];
    wire S1_bit      = state[1];
    wire S11_bit     = state[2];
    wire S110_bit    = state[3];
    wire B0_bit      = state[4];
    wire B1_bit      = state[5];
    wire B2_bit      = state[6];
    wire B3_bit      = state[7];
    wire Count_bit   = state[8];
    wire Wait_bit    = state[9];

    // ============================================================
    // Next-state logic (combinational)
    // ============================================================

    // Default next-state assignments (all bits 0 when not explicitly set)
    wire [9:0] next_state = 10'b0;

    // S next-state: from S with d=0, from S110 with d=0, from Wait with ack=1
    assign next_state[0] = (S_bit & ~d) | (S110_bit & ~d) | (Wait_bit & ack);

    // S1 next-state: from S with d=1
    assign next_state[1] = (S_bit & d);

    // S11 next-state: from S1 with d=1
    assign next_state[2] = (S1_bit & d);

    // S110 next-state: from S11 with d=1
    assign next_state[3] = (S11_bit & d);

    // B0 next-state: from S11 with d=1
    assign next_state[4] = (S11_bit & d);

    // B1 next-state: from B0 (always go to next cycle)
    assign next_state[5] = B0_bit;

    // B2 next-state: from B1 (always go to next cycle)
    assign next_state[6] = B1_bit;

    // B3 next-state: from B2 (always go to next cycle)
    assign next_state[7] = B2_bit;

    // Count next-state: from B3 (always go to next cycle)
    assign next_state[8] = B3_bit;

    // Wait next-state: from Count with done_counting=1
    assign next_state[9] = (Count_bit & done_counting);

    // ============================================================
    // Output logic (Moore machine – outputs depend only on state)
    // ============================================================

    // B3_next: assert when next-state is B3
    assign B3_next = next_state[7];

    // S_next: assert when next-state is S
    assign S_next = next_state[0];

    // S1_next: assert when next-state is S1
    assign S1_next = next_state[1];

    // Count_next: assert when next-state is Count
    assign Count_next = next_state[8];

    // Wait_next: assert when next-state is Wait
    assign Wait_next = next_state[9];

    // shift_ena: active in B0, B1, B2, B3
    assign shift_ena = B0_bit | B1_bit | B2_bit | B3_bit;

    // counting: active in Count state
    assign counting = Count_bit;

    // done: active in Wait state
    assign done = Wait_bit;

endmodule

Prob154_fsm_ps2data.code:
module TopModule (
    input  clk,
    input  reset,
    input  [7:0] in,
    output reg [23:0] out_bytes,
    output reg done
);

    // State encoding
    typedef enum logic [1:0] {
        IDLE   = 2'b00,
        BYTE1  = 2'b01,
        BYTE2  = 2'b10,
        BYTE3  = 2'b11
    } state_t;

    state_t state, next_state;

    // Byte shift register: holds the last 3 valid bytes
    // byte_reg[2] = most recent, byte_reg[1] = middle, byte_reg[0] = oldest
    logic [7:0] byte_reg [2:0];

    // Next-state and datapath logic
    always_ff @(posedge clk or posedge reset) begin
        if (reset) begin
            state      <= IDLE;
            byte_reg[0] <= 8'h00;
            byte_reg[1] <= 8'h00;
            byte_reg[2] <= 8'h00;
            done        <= 1'b0;
            out_bytes   <= 24'h00;
        end else begin
            // Default: keep state and registers
            state      <= next_state;
            done       <= 1'b0;            // done is pulsed low unless we are in the cycle after 3rd byte

            case (state)
                IDLE: begin
                    // Look for first byte with bit 3 set
                    if (in[3]) begin
                        next_state <= BYTE1;
                        // Shift in first byte
                        byte_reg[0] <= in;
                        byte_reg[1] <= 8'h00;
                        byte_reg[2] <= 8'h00;
                    end else begin
                        next_state <= IDLE;
                        // Discard byte
                    end
                end

                BYTE1: begin
                    // Expect second byte
                    next_state <= BYTE2;
                    // Shift: old byte0 -> byte1, new byte in -> byte0
                    byte_reg[1] <= byte_reg[0];
                    byte_reg[0] <= in;
                end

                BYTE2: begin
                    // Expect third byte
                    next_state <= BYTE3;
                    byte_reg[2] <= byte_reg[1];
                    byte_reg[1] <= byte_reg[0];
                    byte_reg[0] <= in;
                end

                BYTE3: begin
                    // Third byte received – next cycle we pulse done
                    next_state <= IDLE;
                    // Build the 24-bit output: byte_reg[2] is first byte, byte_reg[0] is third byte
                    out_bytes <= {byte_reg[2], byte_reg[1], byte_reg[0]};
                    done      <= 1'b1;
                end
            endcase
        end
    end

    // Optional: reset the done flag in the cycle after done is asserted if you want
    // done to be exactly one cycle high. The spec says "signal the receipt of a
    // message once all 3 bytes have been received (done). The FSM should signal
    // done in the cycle immediately after the third byte of each message was
    // successfully received."
    // The above always_comb/always_ff already does this: done is asserted in the
    // BYTE3 state's next-cycle assignment, and then reset to 0 at the start of
    // the next always_ff block iteration (unless we re-enter BYTE3).

endmodule

