module TopModule (
    input  logic clk,
    input  logic reset,
    input  logic in,
    output logic out
);

    // State encoding: 2 bits for 4 states (A, B, C, D)
    typedef enum logic [1:0] {
        A = 2'b00,
        B = 2'b01,
        C = 2'b10,
        D = 2'b11
    } state_t;

    state_t state, next_state;

    // Next-state logic (combinational)
    always_comb begin
        case (state)
            A: begin
                next_state = in ? B : A;
            end
            B: begin
                next_state = B; // in has no effect on B's next state
            end
            C: begin
                next_state = in ? D : A;
            end
            D: begin
                // Follow spec: D with in=0 -> C, in=1 -> B
                next_state = in ? B : C;
            end
            default: next_state = A;
        endcase
    end

    // Output logic (Moore machine: output depends only on state)
    always_comb begin
        case (state)
            A, B, C: out <= 1'b0;
            D:       out <= 1'b1;
            default: out <= 1'b0;
        endcase
    end

    // Next-state flip-flops (sequential logic, positive edge triggered)
    always_ff @(posedge clk or posedge reset) begin
        if (reset)
            state <= A;
        else
            state <= next_state;
    end

endmodule

