module TopModule (
    input  clk,
    input  reset,
    input  data,
    output start_shifting
);

    // Declare start_shifting as logic since it is driven inside an always block
    logic start_shifting;

    // State encoding: 0=S0, 1=S1, 2=S2, 3=S3
    typedef enum logic [1:0] {
        S0 = 2'b00,
        S1 = 2'b01,
        S2 = 2'b10,
        S3 = 2'b11
    } state_t;

    state_t current_state, next_state;

    // State register (synchronous reset, positive edge triggered)
    always_ff @(posedge clk) begin
        if (reset)
            current_state <= S0;
        else
            current_state <= next_state;
    end

    // Next-state logic (combinational)
    always_comb begin
        case (current_state)
            S0: begin
                if (data == 1'b1)
                    next_state = S1;
                else
                    next_state = S0;
            end
            S1: begin
                if (data == 1'b1)
                    next_state = S2;
                else
                    next_state = S0;
            end
            S2: begin
                if (data == 1'b0)
                    next_state = S3;
                else
                    next_state = S1; // on '1', stay in potential start of new sequence
            end
            S3: begin
                if (data == 1'b1)
                    next_state = S0; // sequence 1101 found, reset to S0
                else
                    next_state = S0;
            end
            default: next_state = S0;
        endcase
    end

    // Output logic: assert start_shifting when state reaches S3 (sequence found)
    always_comb begin
        start_shifting = (current_state == S3);
    end

endmodule

