            // Outputs remain default (all high)
        end else begin
            // Determine outputs based on current sensor state and previous state
            case (s)
                // Above s[2]: s[2] is asserted (s[2]=1). Sensors s[0], s[1], s[2] asserted.
                // Nominal flow: None -> all outputs off (high). dfr off.
                3'b1xx: begin
                    fr2 = 1'b1;
                    fr1 = 1'b1;
                    fr0 = 1'b1;
                    dfr = 1'b1;
