                    if (prev_s < s) begin
                        dfr = 1'b0; // Open Supplemental flow valve
                    end else begin
                        dfr = 1'b1; // Keep Supplemental flow valve closed
                    end
                end

                // Between s[1] and s[0]: s[0] asserted, s[1] deasserted. Sensor s[0] asserted.
                // Nominal flow: fr0, fr1. If previous level was lower, open Supplemental (dfr=0).
                3'b001: begin
                    fr0 = 1'b0; // Nominal fr0 on
                    fr1 = 1'b0; // Nominal fr1 on
                    fr2 = 1'b1;
                    if (prev_s < s) begin
                        dfr = 1'b0;
                    end else begin
                        dfr = 1'b1;
                    end
                end

                // Below s[0]: No sensors asserted (s[0]=0, s[1]=0, s[2]=0).
                // Nominal flow: fr0, fr1, fr2. If previous level was lower, open Supplemental (dfr=0).
                default: begin // s == 3'b000
                    fr0 = 1'b0; // Nominal fr0 on
                    fr1 = 1'b0; // Nominal fr1 on
                    fr2 = 1'b0; // Nominal fr2 on
                    if (prev_s < s) begin
                        dfr = 1'b0;
                    end else begin
                        dfr = 1'b1;
                    end
                end
            endcase
        end
    end

    // Sequential logic: update previous sensor state on rising edge of clk
    always_ff @(posedge clk) begin
        if (reset) begin
            prev_s <= 3'b111; // Reset state: equivalent to level low for long time (no sensors asserted, all outputs asserted)
        end else begin
            prev_s <= s;
        end
    end

endmodule

