module TopModule (
    input  clk,
    input  reset,
    output logic [2:0] ena,  // 3 bits: enable for tens, hundreds, thousands
    output logic [15:0] q    // 16 bits: BCD digits
);

// Internal registers for BCD digits
logic [3:0] ones;    // q[3:0]
logic [3:0] tens;    // q[7:4]
logic [3:0] hundreds;// q[11:8]
logic [3:0] thousands;// q[15:12]

// Counter logic
always_ff @(posedge clk or posedge reset) begin
    if (reset) begin
        ones     <= 4'b0;
        tens     <= 4'b0;
        hundreds <= 4'b0;
        thousands <= 4'b0;
    end else begin
        // Increment ones
        ones <= ones + 1'b1;

        // Check carry for ones
        if (ones == 4'd9) begin
            ones <= 4'b0;
            // Increment tens
            tens <= tens + 1'b1;

            // Check carry for tens
            if (tens == 4'd9) begin
                tens <= 4'b0;
                // Increment hundreds
                hundreds <= hundreds + 1'b1;

                // Check carry for hundreds
                if (hundreds == 4'd9) begin
                    hundreds <= 4'b0;
                    // Increment thousands
                    thousands <= thousands + 1'b1;
                end
            end
        end
    end
end

// Assign output q
assign q = {thousands, hundreds, tens, ones};

// Assign enable signals
// ena[0] -> tens enable (asserted when ones == 9)
// ena[1] -> hundreds enable (asserted when tens == 9)
// ena[2] -> thousands enable (asserted when hundreds == 9)
always_comb begin
    ena[0] = (ones == 4'd9);
    ena[1] = (tens == 4'd9);
    ena[2] = (hundreds == 4'd9);
end

endmodule

