module TopModule (
    input  clk,
    input  areset,
    input  bump_left,
    input  bump_right,
    input  ground,
    input  dig,
    output walk_left,
    output walk_right,
    output aaah,
    output digging
);

    // Internal state and control signals
    // State encoding: 3 bits for mode, plus direction-before-fall bit
    // state[2:0] = 3'b000: WALK_LEFT
    // state[2:0] = 3'b001: WALK_RIGHT
    // state[2:0] = 3'b010: FALLING
    // state[2:0] = 3'b011: DIGGING
    // state[2:0] = 3'b100: SPLATTERED
    // state[2] also serves as direction-before-fall when in FALLING: 0 = left, 1 = right
    logic [2:0] state;

    // Falling counter: 20 bits (0 to 19 = 20 cycles; when it reaches 19 and we are still falling next cycle, splatter occurs on ground hit)
    logic [19:0] fall_cnt_reg;

    // is_falling and is_digging flags (could be inferred from state but kept explicit for clarity)
    logic is_falling;
    logic is_digging;

    // Output assignments (Moore state machine - outputs depend only on state)
    assign walk_left  = (state == 3'b000);
    assign walk_right = (state == 3'b001);
    assign aaah       = (state == 3'b010);
    assign digging    = (state == 3'b011);

    // Falling counter update on positive edge of clock
    always_ff @(posedge clk or posedge areset) begin
        if (areset) begin
            fall_cnt_reg <= 20'd0;
        end else begin
            // If falling, increment counter; otherwise reset to 0
            if (is_falling) begin
                if (fall_cnt_reg == 20'd19) begin
                    // Already at max (19), stay at 19 (next cycle splatter detection will use this)
                    fall_cnt_reg <= 20'd19;
                end else begin
                    fall_cnt_reg <= fall_cnt_reg + 1'b1;
                end
            end else begin
                fall_cnt_reg <= 20'd0;
            end
        end
    end

    // State register update on positive edge of clock
    always_ff @(posedge clk or posedge areset) begin
        if (areset) begin
            // Asynchronous reset: go to WALK_LEFT, clear flags
            state <= 3'b000;
            is_falling <= 1'b0;
            is_digging <= 1'b0;
        end else begin
            // Default next state is current state (no change)
            logic [2:0] next_state;
            logic next_is_falling, next_is_digging;

            next_state = state;
            next_is_falling = is_falling;
            next_is_digging = is_digging;

            // Current walking direction (only valid when not falling/digging)
            logic walking_left, walking_right;
            walking_left  = (state == 3'b000);
            walking_right = (state == 3'b001);

            // We also need to remember the walking direction before a fall.
            // Since state[2] when in FALLING encodes that direction, we just use it.

            // --------------------------------------------------------
            // Falling logic (highest precedence)
            // --------------------------------------------------------
            if (!ground) begin
                // Ground = 0
                if (!is_falling) begin
                    // Start falling
                    next_is_falling <= 1'b1;
                    next_state <= 3'b010; // FALLING
                    // direction-before-fall is already in state[2] from previous walking state
                    // fall counter starts at 0
                    fall_cnt_reg <= 20'd0;
                end else begin
                    // Already falling: counter already incrementing
                    // No additional action needed here; counter increments each cycle
                end
            end else begin
                // ground = 1
                if (is_falling) begin
                    // Ground reappeared while falling
                    if (fall_cnt_reg == 20'd19) begin
                        // Fell for more than 20 cycles (counter reached 19 and still falling) -> splatter
                        next_state <= 3'b100; // SPLATTERED
                        next_is_falling <= 1'b0;
                        next_is_digging <= 1'b0;
                        // fall_cnt_reg stays at 19 (or could reset, but outputs are 0 anyway)
                    end else begin
                        // Fell for <= 20 cycles -> resume walking in same direction
                        // state[2] remembers the direction before fall
                        next_is_falling <= 1'b0;
                        // Keep the direction bit (state[2]) as is; next state will be WALK_LEFT or WALK_RIGHT
                        // based on that bit combined with the mode bits.
                        // We need to set next_state to walking mode with the remembered direction.
                        if (state[2]) begin
                            next_state <= 3'b001; // WALK_RIGHT
                        end else begin
                            next_state <= 3'b000; // WALK_LEFT
                        end
                    end
                end else begin
                    // Not falling, ground = 1
                    // Check for digging start
                    // Can start digging if not already falling/digging, ground=1, and dig=1
                    if (!is_digging && dig) begin
                        next_is_digging <= 1'b1;
                        next_state <= 3'b011; // DIGGING
                    end
                    // Direction switching has lower precedence than digging.
                    // If not digging and not falling, bumps can switch direction.
                    // But digging takes precedence, so if we started digging above,
                    // we skip direction switching for this cycle.
                end
            end

            // --------------------------------------------------------
            // Digging logic (second precedence)
            // --------------------------------------------------------
            // If already digging, continue digging until ground=0
            if (is_digging) begin
                if (!ground) begin
                    // Ground disappeared while digging -> start falling
                    next_is_falling <= 1'b1;
                    next_state <= 3'b010; // FALLING
                    fall_cnt_reg <= 20'd0;
                    // Direction-before-fall is the current walking direction.
                    // Since we were digging, we need to preserve the direction we were walking before dig.
                    // The spec says: "A Lemming can dig if it is currently walking on ground".
                    // When ground disappears during digging, we fall and resume original walking direction.
                    // We can infer the original direction from the fact that we were walking before digging.
                    // To keep it simple, we store the direction in state[2] when transitioning to DIGGING
                    // from a walking state. Let's do that below.
                end
                // If ground=1 and still digging, stay digging (continue until ground=0)
            end

            // --------------------------------------------------------
            // Direction switching (lowest precedence, only when not falling/digging)
            // --------------------------------------------------------
            // If not falling and not digging, bumps can switch direction
            if (!is_falling && !is_digging) begin
                // Check bumps: bump_left -> walk_right, bump_right -> walk_left, both -> switch
                if (bump_left && bump_right) begin
                    // Bumped on both sides: switch direction
                    if (walking_left) begin
                        next_state <= 3'b001; // WALK_RIGHT
                    end else if (walking_right) begin
                        next_state <= 3'b000; // WALK_LEFT
                    end
                end else if (bump_left) begin
                    // Bumped on left: walk right
                    next_state <= 3'b001; // WALK_RIGHT
                end else if (bump_right) begin
                    // Bumped on right: walk left
                    next_state <= 3'b000; // WALK_LEFT
                end
                // If neither bump, state stays as is (already default from default assignment)
            end

            // When transitioning to DIGGING from a walking state, store the walking direction in state[2]
            // We do this by checking if we are starting digging while walking.
            // The above logic already sets next_state to DIGGING (3'b011) when !is_digging && dig && ground=1.
            // At that moment, the current state[2] is the walking direction.
            // We need to preserve that direction into the DIGGING state.
            // Since DIGGING state encoding is 3'b011, we can use state[2] as the direction bit.
            // Let's adjust: when starting digging, set state[2] to the current walking direction.
            // The simplest way: in the block where we set next_state <= 3'b011, also set the direction bit.
            // But next_state is 3 bits; we can use the most significant bit of the 3 as direction.
            // However, the encoding defines state[2:0] with specific values.
            // We need to reconcile: DIGGING = 3'b011, but we also need a direction bit.
            // We can repurpose state[2] for direction when in DIGGING, but that changes the encoding.
            // Alternative: use a separate register for direction-before-fall/dig.
            // Given the module already uses state[2] for direction when falling, let's extend that.
            // We'll keep state[2:0] encoding as defined, and add a separate register dir_reg.
            // But the previous code snippet used state[2] for direction-before-fall.
            // Let's re-examine the spec: "when ground reappears (ground=1), the Lemming will resume walking in the same direction as before the fall."
            // We need to remember direction during fall. Using state[2] during FALLING (3'b010) is fine.
            // During DIGGING (3'b011), we also need to remember direction for when ground disappears.
            // To avoid complexity, we can use state[2] for direction in both FALLING and DIGGING,
            // and when transitioning back to walking, use that bit.
            // The encoding table in the original code had:
            // 3'b000: WALK_LEFT, 3'b001: WALK_RIGHT, 3'b010: FALLING, 3'b011: DIGGING, 3'b100: SPLATTERED
            // If we use state[2] as direction, then:
            // - WALK_LEFT would be 3'b000 (state[2]=0)
            // - WALK_RIGHT would be 3'b001 (state[2]=0) -> this conflicts if we need state[2]=1 for right.
            // So we cannot simply use state[2] for both walking modes and direction.
            // We need a separate register. Let's add dir_reg.

            // Let's restructure with a dedicated direction register.
            // We'll declare it outside the always blocks.

            // Update state register
            state <= next_state;
            is_falling <= next_is_falling;
            is_digging <= next_is_digging;
        end
    end

    // Direction-before-fall/dig register
    logic dir_reg; // 1 = was walking right before fall/dig, 0 = was walking left

    always_ff @(posedge clk or posedge areset) begin
        if (areset) begin
            dir_reg <= 1'b0;
        end else begin
            // Update dir_reg when transitioning to FALLING or DIGGING from walking state
            // Also update when switching direction while walking
            // For simplicity, we update dir_reg based on the next_state logic.
            // We'll need to capture the direction before it changes.

            // Let's recompute here to keep it clean.
            // Actually, we can integrate dir_reg updates into the main state always_ff block
            // by capturing the direction at the right moments.
            // Given the complexity, let's refactor the main always_ff to include dir_reg updates.
        end
    end

    // To avoid getting lost in the refactoring, let's write the complete module cleanly from here.
    // We'll use dir_reg as a separate flip-flop.

    // Re-declaring dir_reg properly
    logic dir_reg;

    always_ff @(posedge clk or posedge areset) begin
        if (areset) begin
            state <= 3'b000;
            is_falling <= 1'b0;
            is_digging <= 1'b0;
            dir_reg <= 1'b0;
            fall_cnt_reg <= 20'd0;
        end else begin
            logic [2:0] next_state;
            logic next_is_falling, next_is_digging;
            logic [2:0] next_state_dir; // temporary for direction-aware next state

            next_state = state;
            next_is_falling = is_falling;
            next_is_digging = is_digging;

            // Walking direction signals
            logic walking_left, walking_right;
            walking_left  = (state == 3'b000);
            walking_right = (state == 3'b001);

            // --- Falling logic (highest precedence) ---
            if (!ground) begin
                if (!is_falling) begin
                    next_is_falling <= 1'b1;
                    next_state <= 3'b010; // FALLING
                    fall_cnt_reg <= 20'd0;
                    // dir_reg remembers the walking direction before fall
                    // We need to set dir_reg here based on current state.
                    // But we are about to change state; we can set dir_reg from current walking state.
                    if (walking_left) dir_reg <= 1'b0;
                    else if (walking_right) dir_reg <= 1'b1;
                end
            end else begin
                if (is_falling) begin
                    if (fall_cnt_reg == 20'd19) begin
                        next_state <= 3'b100; // SPLATTERED
                        next_is_falling <= 1'b0;
                        next_is_digging <= 1'b0;
                    end else begin
                        next_is_falling <= 1'b0;
                        // Resume walking in same direction as before fall (dir_reg)
                        if (dir_reg) begin
                            next_state <= 3'b001; // WALK_RIGHT
                        end else begin
                            next_state <= 3'b000; // WALK_LEFT
                        end
                    end
                end else begin
                    // Not falling, ground = 1
                    // --- Digging logic ---
                    if (!is_digging && dig) begin
                        next_is_digging <= 1'b1;
                        next_state <= 3'b011; // DIGGING
                        // dir_reg: remember the walking direction before digging
                        if (walking_left) dir_reg <= 1'b0;
                        else if (walking_right) dir_reg <= 1'b1;
                    end
                    // If already digging, stay digging until ground=0 (handled below)
                end
            end

            // --- If already digging, check for ground disappearance ---
            if (is_digging) begin
                if (!ground) begin
                    next_is_falling <= 1'b1;
                    next_state <= 3'b010; // FALLING
                    fall_cnt_reg <= 20'd0;
                    // dir_reg already holds the direction before dig, which is the original walking direction
                    // No need to update dir_reg here; it's already set from when digging started
                end
                // If ground=1 and still digging, stay digging (next_state remains DIGGING)
            end

            // --- Direction switching (lowest precedence, only when not falling/digging) ---
            if (!is_falling && !is_digging) begin
                if (bump_left && bump_right) begin
                    if (walking_left) next_state <= 3'b001;
                    else if (walking_right) next_state <= 3'b000;
                end else if (bump_left) begin
                    next_state <= 3'b001; // WALK_RIGHT
                end else if (bump_right) begin
                    next_state <= 3'b000; // WALK_LEFT
                end
            end

            // When transitioning to DIGGING from walking, dir_reg is set above.
            // When transitioning to FALLING from walking, dir_reg is set above.
            // When resuming from FALLING, we use dir_reg which was set before fall.
            // When resuming from DIGGING ground disappearance, dir_reg holds the original walking direction.

            state <= next_state;
            is_falling <= next_is_falling;
            is_digging <= next_is_digging;
        end
    end

    // Assign outputs based on state
    assign walk_left  = (state == 3'b000);
    assign walk_right = (state == 3'b001);
    assign aaah       = (state == 3'b010);
    assign digging    = (state == 3'b011);

endmodule
